python
def wordSlipsPositiveProofStrip(line):
    a=line
    out=[]
    length=0
    for c in a+' ':
        if c==' ':
            if length: out.append(length)
            length=0
        else: length+=1
    return [x for x in out if x>0]


java
class Solution {
  public int[] wordSlipsPositiveProofStrip(String line) {
    String a=line; List<Integer> out=new ArrayList<>();
    {int len=0;for(int i=0;i<=a.length();i++){if(i==a.length()||a.charAt(i)==' '){if(len>0)out.add(len);len=0;}else len++;}}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
